-- Generic attract-mode recorder.
-- DO NOT EDIT THIS FILE TO ADD A NEW GAME. Instead, drop a YAML in
-- config/attract_recording/<game_id>.yaml and the launcher
-- (scripts/teach_attract.py) will generate a Lua companion config and
-- pass it via the ARCADEIA_ATTRACT_CFG env var.
--
-- Two recording modes:
--   mode = "tile"   → tile-based playfield (atetris-style).
--                     Reads tile codes from a grid in maincpu RAM,
--                     detects background (most-frequent code), computes
--                     heights/depths/active-piece cells.
--   mode = "sprite" → sprite-based playfield (wboy/gngb/outrun-style).
--                     Dumps {code, sx, sy} for every non-zero sprite in
--                     spriteram.
--
-- Both modes log per-frame to logs/demos/attract_<game_id>_*.jsonl and
-- exit MAME cleanly after `record_seconds`.

local ROOT = os.getenv("ARCADEIA_ROOT") or "/Users/pablo/Documents/arcade-ai"
local cfg_path = os.getenv("ARCADEIA_ATTRACT_CFG")
if not cfg_path or cfg_path == "" then
    print("[teach_attract] FATAL: ARCADEIA_ATTRACT_CFG env var not set")
    return
end

local ok, cfg = pcall(dofile, cfg_path)
if not ok or type(cfg) ~= "table" or not cfg.mode then
    print("[teach_attract] FATAL: bad config at " .. tostring(cfg_path))
    return
end

local LOG_DIR = ROOT .. "/logs/demos"
os.execute("mkdir -p " .. LOG_DIR)
local SESSION = "attract_" .. cfg.game_id .. "_" .. os.date("%Y%m%d_%H%M%S")
local LOG_PATH = LOG_DIR .. "/" .. SESSION .. ".jsonl"
local RECORD_FRAMES = (cfg.record_seconds or 60) * 60
local SAMPLE_EVERY = cfg.sample_every or 4
local BOOT_SKIP = cfg.boot_skip_frames or 0

local log = io.open(LOG_PATH, "w")
if not log then
    print("[teach_attract] FATAL: cannot open " .. LOG_PATH)
    return
end

local function meta_kv(k, v)
    return string.format('"%s":%s', k, type(v) == "string" and
        string.format('"%s"', v) or tostring(v))
end

log:write(string.format(
    '{"type":"meta","frame":0,"session":"%s","game_id":"%s","mode":"%s","record_seconds":%d,"sample_every":%d,"boot_skip":%d,"rom":"%s","cfg":"%s"}\n',
    SESSION, cfg.game_id, cfg.mode,
    cfg.record_seconds or 60, SAMPLE_EVERY, BOOT_SKIP,
    cfg.rom or "", cfg_path
))
log:flush()

local cpu = manager.machine.devices[":maincpu"]
local mem = cpu.spaces["program"]

-- ============================================================== --
-- TILE MODE
-- ============================================================== --

local function tile_read(base, bpc, col_count, row, col)
    local idx = row * col_count + col
    local addr = base + idx * bpc
    if bpc == 1 then return mem:read_u8(addr) end
    local b0 = mem:read_u8(addr)
    local b1 = mem:read_u8(addr + 1)
    return b0 | ((b1 & 7) << 8)
end

local function detect_bg(t, rlo, rhi, clo, chi)
    local counts, best, best_n = {}, 0, -1
    for row = rlo, rhi do
        for col = clo, chi do
            local c = tile_read(t.base, t.bytes_per_cell, t.col_count, row, col)
            counts[c] = (counts[c] or 0) + 1
            if counts[c] > best_n then best_n, best = counts[c], c end
        end
    end
    return best
end

local function compute_heights(t, bg, clo, chi, rlo, rhi)
    local heights = {}
    for col = clo, chi do
        local top = rhi + 1
        for row = rlo, rhi do
            if tile_read(t.base, t.bytes_per_cell, t.col_count, row, col) ~= bg then
                top = row; break
            end
        end
        heights[#heights + 1] = top
    end
    return heights
end

local function find_active_piece(t, bg, clo, chi, rlo, rhi)
    local min_row = rhi + 1
    for row = rlo, rhi do
        for col = clo, chi do
            if tile_read(t.base, t.bytes_per_cell, t.col_count, row, col) ~= bg
                and row < min_row then
                min_row = row
            end
        end
    end
    if min_row > rhi then return {}, min_row end
    local cells = {}
    for row = min_row, math.min(min_row + 3, rhi) do
        for col = clo, chi do
            if tile_read(t.base, t.bytes_per_cell, t.col_count, row, col) ~= bg then
                cells[#cells + 1] = { row = row, col = col }
            end
        end
    end
    return cells, min_row
end

local function cells_to_str(cells, sep)
    if #cells == 0 then return "" end
    local parts = {}
    for _, c in ipairs(cells) do
        parts[#parts + 1] = c.row .. ":" .. c.col
    end
    table.sort(parts)
    return table.concat(parts, sep or ";")
end

local function cells_bbox(cells)
    local l, r, top = -1, -1, -1
    for _, c in ipairs(cells) do
        if l == -1 or c.col < l then l = c.col end
        if r == -1 or c.col > r then r = c.col end
        if top == -1 or c.row < top then top = c.row end
    end
    return l, r, top
end

local function join(arr)
    return table.concat(arr, ",")
end

local function stack_depths(t, bg, cells, pclo, pchi, prlo, prhi)
    -- Replica de stack_depths_for_piece() del extractor atetris.
    -- depth[col] = cuántas filas de stack debajo de la pieza activa hay
    -- en esa columna (0 si la pieza está tocando el suelo o no hay stack).
    local piece_rows = {}
    for _, c in ipairs(cells) do piece_rows[c.row] = true end
    local d = {}
    for col = pclo, pchi do
        local depth = 0
        for row = prhi, prlo, -1 do
            if piece_rows[row] then
                -- skip celdas de la pieza activa (goto continue)
            elseif tile_read(t.base, t.bytes_per_cell, t.col_count, row, col) ~= bg then
                depth = prhi - row + 1
                break
            end
        end
        d[#d + 1] = depth
    end
    return d
end

local function record_tile(cfg, frame)
    local t = cfg.tile
    local bg_rlo, bg_rhi = t.bg_scan_rows[1], t.bg_scan_rows[2]
    local bg_clo, bg_chi = t.bg_scan_cols[1], t.bg_scan_cols[2]
    local prlo, prhi     = t.play_rows[1],    t.play_rows[2]
    local pclo, pchi     = t.play_cols[1],    t.play_cols[2]
    local bg = detect_bg(t, bg_rlo, bg_rhi, bg_clo, bg_chi)
    local heights = compute_heights(t, bg, pclo, pchi, prlo, prhi)
    local cells, min_row = find_active_piece(t, bg, pclo, pchi, prlo, prhi)
    local depths = stack_depths(t, bg, cells, pclo, pchi, prlo, prhi)
    local pl, pr, pt = cells_bbox(cells)
    log:write(string.format(
        '{"frame":%d,"mode":"tile","bg":%d,"min_row":%d,' ..
        '"heights":[%s],"depths":[%s],' ..
        '"piece_sig":"%s","piece_cells":"%s",' ..
        '"piece_left":%d,"piece_right":%d,"piece_top":%d}\n',
        frame, bg, min_row, join(heights), join(depths),
        cells_to_str(cells, ","), cells_to_str(cells, ";"),
        pl, pr, pt
    ))
end

-- ============================================================== --
-- SPRITE MODE
-- ============================================================== --

local function record_sprite(cfg, frame)
    local s = cfg.sprite
    local ignore = {}
    if s.ignore_codes then
        for _, c in ipairs(s.ignore_codes) do ignore[c] = true end
    end
    -- end_marker (opcional): corta el bucle cuando una entrada está vacía/
    -- terminada. OutRun usa bit 15 del word +0 (high byte del LE-u16).
    -- end_byte_offset + end_mask configuran esto sin tocar el código Lua.
    local em = s.end_marker
    local parts = {}
    local count = 0
    for i = 0, s.sprite_count - 1 do
        local base = s.base + i * s.stride
        if em then
            local b = mem:read_u8(base + em.offset)
            if (b & em.mask) ~= 0 then break end
        end
        local code = mem:read_u8(base + s.code_offset)
        if code ~= 0 and not ignore[code] then
            local raw_x = mem:read_u8(base + s.x_raw_offset)
            local raw_y = mem:read_u8(base + s.y_raw_offset)
            local sx = raw_x + s.x_offset
            local sy
            if s.y_transform == "flip" then
                sy = 256 - raw_y
            elseif s.y_transform == "offset" then
                sy = raw_y - 0x100  -- for hardware with signed Y
            else
                sy = raw_y
            end
            parts[#parts + 1] = string.format('{"c":%d,"x":%d,"y":%d,"s":%d}', code, sx, sy, i)
            count = count + 1
        end
    end
    log:write(string.format(
        '{"frame":%d,"mode":"sprite","count":%d,"sprites":[%s]}\n',
        frame, count, table.concat(parts, ",")
    ))
end

-- ============================================================== --
-- Frame loop
-- ============================================================== --

local frame = 0
emu.register_frame_done(function()
    frame = frame + 1
    if frame <= BOOT_SKIP then return end
    if (frame - BOOT_SKIP) % SAMPLE_EVERY ~= 0 then return end
    if cfg.mode == "tile" then record_tile(cfg, frame)
    elseif cfg.mode == "sprite" then record_sprite(cfg, frame)
    else
        log:write(string.format('{"frame":%d,"mode":"%s","error":"unknown mode"}\n', frame, tostring(cfg.mode)))
    end
    if frame % 240 == 0 then log:flush() end
    if frame >= RECORD_FRAMES then
        log:write(string.format('{"type":"end","session":"%s","frames":%d}\n', SESSION, frame))
        log:close()
        manager.machine:exit()
    end
end)

local screen = manager.machine.screens[":screen"]
if screen then
    emu.register_frame_done(function()
        screen:draw_text(4, 4,
            string.format("ATTRACT REC  %s  f%d/%d", cfg.game_id, frame, RECORD_FRAMES),
            0xffffffff, 0xff000000)
        screen:draw_text(4, 16, "no coin — observe only", 0xffccff66, 0xff000000)
        screen:draw_text(4, 28, string.format("mode=%s sample=1/%d", cfg.mode, SAMPLE_EVERY),
            0xffaaffaa, 0xff000000)
    end)
end